export interface ComprehensiveCountryData {
  id: string;
  name: string;
  flag: string;
  continent: 'Asia' | 'Europe' | 'Africa' | 'North America' | 'South America' | 'Oceania';
  capital: string;
  currency: string;
  visaRequiredForBD: boolean;
  visaTypeSummary: string; // e.g. "Sticker Visa (Embassy Dhaka)", "E-Visa (Online)", "Visa on Arrival"
  eVisaAvailable: boolean;
  visaOnArrival: boolean;
  submissionLocation: string; // "Dhaka, Bangladesh" or "New Delhi, India" or "Online Portal"
  processingTime: string;
  embassyFeeRange: string;
  biometricRequired: boolean;
  interviewRequired: boolean;
  popularDestination: boolean;
  customDetails?: Partial<DetailedCountryReport>;
}

export interface DetailedCountryReport {
  countryOverview: string;
  doBDBitizensNeedVisa: string;
  visaTypes: string[];
  visaCategories: string[];
  eVisaAvailability: string;
  visaOnArrivalAvailability: string;
  submissionRequirement: string;
  biometricRequirement: string;
  interviewRequirement: string;
  passportValidity: string;
  photoRequirements: string;
  bankStatementRequirements: string;
  travelHistoryRequirements: string;
  invitationLetterRequirements: string;
  sponsorRequirements: string;
  employmentDocuments: string[];
  educationalDocuments: string[];
  applicationProcess: string[];
  appointmentProcess: string;
  processingTime: string;
  embassyFee: string;
  agencyServiceFee: string;
  commonRefusalReasons: string[];
  documentsChecklist: string[];
  latestUpdateDate: string;
  faqs: { question: string; answer: string }[];
  disclaimer: string;
}

