/**
 * Generates the full 29-point official report for ANY of the 190 countries
 * in exact accordance with the user's requested template.
 */
export function generate29PointCountryReport(country: ComprehensiveCountryData): DetailedCountryReport {
  const isDhakaSubmission = country.submissionLocation.toLowerCase().includes('dhaka');
  const isOnline = country.eVisaAvailable || country.submissionLocation.toLowerCase().includes('online');
  const isVoA = country.visaOnArrival && !country.visaRequiredForBD;

  return {
    // 1. Country Overview
    countryOverview: `${country.name} is a sovereign country situated in ${country.continent} with its capital at ${country.capital}. Its official currency is ${country.currency}. As an international travel and business destination, it enforces strict consular entry criteria governed by its national immigration department.`,

    // 2. Do Bangladeshi Citizens Need a Visa?
    doBDBitizensNeedVisa: isVoA
      ? `Bangladeshi citizens can enter ${country.name} with ${country.visaTypeSummary}. Standard entry clearance requires an unexpired passport (min 6 months), return air ticket, and confirmed accommodation.`
      : `Yes. Ordinary Bangladeshi passport holders require a valid visa prior to departure or an approved pre-entry clearance to travel to ${country.name}.`,

    // 3. Visa Types
    visaTypes: [
      `Tourist / Visitor Visa (${country.name} Short-Stay)`,
      `Business & Commercial Consultation Visa`,
      `Official / Diplomatic Visa`,
      `Transit Visa (Airside / Landside)`,
      `Student & Academic Research Permit`,
      `Employment / Work Visa (Requires Authorized Local Sponsor)`,
    ],

    // 4. Visa Categories
    visaCategories: [
      'Single Entry (Standard 30 to 90 Days validity)',
      'Double Entry (For round-trip transit itineraries)',
      'Multiple Entry (Typically 6 months, 1 year, or up to 5/10 years for eligible travel histories)',
    ],

    // 5. E-Visa Availability
    eVisaAvailability: country.eVisaAvailable
      ? `Yes. ${country.name} supports electronic visa processing through its official government immigration portal for eligible Bangladeshi passport holders.`
      : `No official e-Visa is universally available for ordinary Bangladeshi passport holders. Applications must be submitted via physical consular dossier or authorized processing centers.`,

    // 6. Visa on Arrival Availability
    visaOnArrivalAvailability: country.visaOnArrival
      ? `Yes. Eligible Bangladeshi travelers can obtain an entry permit upon arrival at international border checkpoints, subject to return tickets and hotel proof.`
      : `No Visa on Arrival is available for ordinary Bangladeshi passport holders traveling to ${country.name}. Visa must be approved prior to airline boarding.`,

    // 7. Embassy / VFS Submission Requirement
    submissionRequirement: isOnline
      ? `Applications are completed online via the official ${country.name} immigration portal, followed by biometric verification where applicable.`
      : isDhakaSubmission
      ? `Physical submission is handled through the Embassy/High Commission of ${country.name} or designated VFS Global / consular center in Dhaka, Bangladesh.`
      : `Because ${country.name} does not maintain an independent resident consular mission in Dhaka, applications from Bangladesh are concurrently accredited to and processed via its Embassy in ${country.submissionLocation}.`,

    // 8. Biometric Requirement
    biometricRequirement: country.biometricRequired
      ? `Mandatory: All applicants aged 12 and above must provide 10-digit digital fingerprint scans and live facial biometric photographs at the authorized application center.`
      : `Biometrics not routinely required for standard short-stay tourist applications unless requested by the consular officer during file review.`,

    // 9. Interview Requirement
    interviewRequirement: country.interviewRequired
      ? `Mandatory: Consular interview required in person at the diplomatic mission prior to visa issuance.`
      : `Interviews are generally waived for tourist categories. However, the consular section reserves the statutory right to request an in-person or video interview if documentation clarity is needed.`,

    // 10. Passport Validity
    passportValidity: `Your Machine Readable Passport (MRP) or e-Passport must have at least 6 months remaining validity from your scheduled date of departure from ${country.name}, with at least 2 consecutive blank visa pages.`,

    // 11. Photo Requirements
    photoRequirements: `Two recent identical passport-sized color photographs taken within the last 3 months on a pure white background. Dimensions: 35mm x 45mm (or 2x2 inches where specified), 80% face coverage, no eyeglasses, no reflections, and neutral facial expression.`,

    // 12. Bank Statement Requirements
    bankStatementRequirements: `Original 6-month bank statement with official bank seal and signature, accompanied by a Bank Solvency Certificate. Transactions should demonstrate consistent, genuine income without sudden, unexplained large cash deposits. Average daily balance must sufficiently support your travel itinerary.`,

    // 13. Travel History Requirements
    travelHistoryRequirements: `All previous passports displaying valid entry/exit stamps, past visas (such as Southeast Asia, Middle East, UK, US, or Schengen), and expired travel documents must be submitted to substantiate authentic bona fide traveler history.`,

    // 14. Invitation Letter Requirements
    invitationLetterRequirements: `For business or personal visits: Formal invitation letter from the host entity or family member in ${country.name}, detailing the exact purpose of visit, relationship, duration, residential address, and explicit financial undertaking for your stay.`,

    // 15. Sponsor Requirements
    sponsorRequirements: `If travel is sponsored: Sponsor's official letter of sponsorship, proof of legal residence/citizenship in ${country.name}, recent tax assessments (e.g. W2, Notice of Assessment), and 3 to 6 months bank statements proving financial capacity.`,

    // 16. Employment Documents
    employmentDocuments: [
      'For Salaried Employees: Forwarding / No Objection Certificate (NOC) on official company letterhead detailing designation, joining date, monthly salary, and approved leave duration.',
      'Last 3 to 6 months pay slips and company salary account bank statement.',
      'For Business Owners: Valid Trade License (notarized English translation), Memorandum of Articles / Partnership Deed, IRC/ERC, and Company Bank Statements.',
      'For Professionals: Official membership registration (e.g. BMDC for Doctors, Bar Council for Lawyers, BTEB/IEB for Engineers).',
      'For Students: Student ID copy, leave approval letter, and enrollment certificate from recognized school/college/university.',
    ],

    // 17. Educational Documents
    educationalDocuments: [
      'Highest academic certificates and transcripts (SSC, HSC, Bachelor’s, or Master’s degrees).',
      'For student visa applications: Official Unconditional Offer Letter / Confirmation of Acceptance, English proficiency scorecards (IELTS, TOEFL, PTE), and verified tuition fee payment receipts.',
    ],

    // 18. Application Process
    applicationProcess: [
      `Step 1: Document audit and eligibility profile evaluation at VisaHOBe.`,
      `Step 2: Preparing verified document checklist tailored to ${country.name} immigration standards.`,
      `Step 3: Meticulous completion of the official online or consular application form with zero discrepancies.`,
      `Step 4: Scheduling biometric appointment or consular submission slot at the authorized center.`,
      `Step 5: File submission, biometric capture, and payment of official embassy processing fees.`,
      `Step 6: Live tracking through VisaHOBe Client Portal until passport courier return.`,
    ],

    // 19. Appointment Process
    appointmentProcess: isOnline && !country.biometricRequired
      ? `Online submission does not require in-person appointment. Files and digital photos are transmitted securely through the official portal.`
      : `Appointments are booked through official scheduling systems (VFS Global, embassy online calendar, or designated mission portal). Applicants receive a confirmation slip with QR barcode for security entrance.`,

    // 20. Processing Time
    processingTime: country.processingTime,

    // 21. Embassy / VFS Fee
    embassyFee: country.embassyFeeRange,

    // 22. Agency Service Fee
    agencyServiceFee: `VisaHOBe administrative consultancy fee: BDT 3,500 to 10,000 depending on single/multiple category, form filling, and checklist complexity. Consular fees are separated and paid at actuals with itemized receipts.`,

    // 23. Common Refusal Reasons
    commonRefusalReasons: [
      'Inadequate or inconsistent financial documentation; sudden unexplained large deposits into bank account.',
      'Weak economic, family, or employment ties to Bangladesh, raising consular doubts regarding genuine return intent.',
      'Unclear or unrealistic day-by-day travel itinerary with mismatched hotel and flight bookings.',
      'Failure to disclose prior visa refusals, resulting in credibility issues or statutory misrepresentation.',
      'Incomplete employment documentation or unverified employer contact details.',
    ],

    // 24. Required Documents Checklist
    documentsChecklist: [
      'Original Current Passport (valid min 6 months) + all Old Passports',
      'Completed and signed Visa Application Form',
      '2 Recent Color Photos (white background, 35x45mm or 2x2 in)',
      'Original Bank Statement (last 6 months) + Bank Solvency Certificate',
      'Official NOC / Leave Letter from Employer OR Business Trade License (translated & notarized)',
      'Salary Pay Slips / Business Tax Return / TIN Certificate',
      'Round-trip Flight Reservation and Confirmed Hotel Bookings',
      'Comprehensive Travel Health Insurance (mandatory for Schengen/Europe and select countries)',
      'Detailed Cover Letter outlining purpose of visit and commitment to return to Bangladesh',
    ],

    // 25. Latest Update Date
    latestUpdateDate: `Verified: ${new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' })} Consular Rules`,

    // 26. Apply Now CTA: Handled in UI
    // 27. Book Consultation CTA: Handled in UI

    // 28. FAQ
    faqs: [
      {
        question: `Can VisaHOBe guarantee that my ${country.name} visa will be approved?`,
        answer: `No. Visa decisions are made solely and independently by the visa officers of the ${country.name} embassy or immigration department. VisaHOBe provides professional documentation review and procedural assistance to ensure your file meets official standards.`,
      },
      {
        question: `How much bank balance is required for ${country.name}?`,
        answer: `Most embassies do not state a rigid minimum balance; rather, they look for consistent transactions and an average balance sufficient to cover round-trip airfare, accommodation, and daily expenses (typically $80 to $150 per day) without exhausting your savings.`,
      },
      {
        question: `What if I have had a previous visa refusal for another country?`,
        answer: `Always declare past refusals truthfully. Most international immigration systems share data. Concealing a refusal is considered misrepresentation and leads to mandatory rejection, whereas honest disclosure with improved documentation can still lead to approval.`,
      },
      {
        question: `How are government embassy fees paid?`,
        answer: `Official government fees are paid directly to designated embassy bank accounts, VFS counters, or official government portals. VisaHOBe provides itemized payment tracking with zero hidden charges.`,
      },
    ],

    // 29. Disclaimer
    disclaimer: `VisaHOBe is an independent administrative visa support agency. We are not an embassy, consulate, or government department. All visa approvals, processing times, and entry clearances remain under the exclusive jurisdiction of the ${country.name} government.`,
  };
}
